input.contents:
$ErrorActionPreference = 'Stop'
$files = @(
  'C:\Users\carys\cts\.cursor\nd-scan\prio_1.1_nocmp.json',
  'C:\Users\carys\cts\.cursor\nd-scan\prio_1.2_suspect.json',
  'C:\Users\carys\cts\.cursor\nd-scan\prio_1.3_suspect.json'
)
foreach ($f in $files) {
  Write-Host "=== $f ==="
  $raw = Get-Content -LiteralPath $f -Raw
  $j = $raw | ConvertFrom-Json
  if ($j -is [System.Array]) {
    Write-Host ("count=" + $j.Count)
    $j[0] | ConvertTo-Json -Depth 6 | Write-Host
  } else {
    Write-Host ("keys=" + ($j.PSObject.Properties.Name -join ','))
    foreach ($k in @('candidates','findings','items','suspects','rows','matches')) {
      if ($j.PSObject.Properties.Name -contains $k) {
        $arr = $j.$k
        Write-Host ("$k count=" + $arr.Count)
        $arr[0] | ConvertTo-Json -Depth 6 | Write-Host
        break
      }
    }
  }
}

$ErrorActionPreference = 'Stop'
$outDir = 'C:\Users\carys\cts\.cursor\nd-scan'

# --- 1.1: filter pointer-ish sorts ---
$p11 = Get-Content -LiteralPath "$outDir\prio_1.1_nocmp.json" -Raw | ConvertFrom-Json
$ptrHints = @(
  '\*',
  'Ptr',
  'ptr',
  'Node',
  'Term',
  'Net',
  'Pin',
  'Obj',
  'Driver',
  'Cell',
  'Inst',
  'Edge',
  'Gate',
  'Port',
  'Wire',
  'Buffer',
  'Clock',
  'Sink',
  'Source'
)
$numericDismiss = @(
  'float', 'double', 'int', 'long', 'size_t', 'unsigned', 'MsgId', 'msgId',
  'Index', 'index', 'Id\b', 'ids\b', 'Ids\b', 'cost', 'delay', 'slack',
  'ratio', 'score', 'weight', 'priority', 'rank', 'level'
)

$ptrCandidates = @()
$numericLike = @()
$other = @()
foreach ($c in $p11) {
  $chunk = [string]$c.chunk
  $file = [string]$c.file
  # extract sort arg roughly
  $isNumericName = $false
  foreach ($n in $numericDismiss) {
    if ($chunk -match $n) { $isNumericName = $true; break }
  }
  $looksPtr = $false
  if ($chunk -match '\*') { $looksPtr = $true }
  foreach ($h in $ptrHints) {
    if ($chunk -match $h) { $looksPtr = $true; break }
  }
  # default two-arg sort of something named *Ids etc is numeric
  if ($isNumericName -and -not ($chunk -match '\*')) {
    $numericLike += $c
  } elseif ($looksPtr -or -not $isNumericName) {
    $ptrCandidates += $c
  } else {
    $other += $c
  }
}
Write-Host "1.1 total=$($p11.Count) ptrish=$($ptrCandidates.Count) numericish=$($numericLike.Count) other=$($other.Count)"
$ptrCandidates | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath "$outDir\_1.1_ptrish.json"
Write-Host "--- 1.1 ptrish sample ---"
$ptrCandidates | Select-Object -First 40 | ForEach-Object { "{0}:{1}  {2}" -f $_.file, $_.line, $_.chunk }

# --- 1.2: priority file filter + top files ---
$p12 = Get-Content -LiteralPath "$outDir\prio_1.2_suspect.json" -Raw | ConvertFrom-Json
$prio12 = $p12 | Where-Object {
  $_.file -match 'ctsSplitState|ctssch|NodeList|ctsIntSkewGroupBal|ccd/'
}
Write-Host "`n1.2 total=$($p12.Count) priority-filtered=$($prio12.Count)"
$prio12 | Select-Object -First 60 | ForEach-Object { "{0}:{1}  {2}" -f $_.file, $_.line, $_.text }

Write-Host "`n--- 1.2 top files by count ---"
$p12 | Group-Object file | Sort-Object Count -Descending | Select-Object -First 25 | ForEach-Object { "{0,4} {1}" -f $_.Count, $_.Name }

# --- 1.3: priority + top files ---
$p13 = Get-Content -LiteralPath "$outDir\prio_1.3_suspect.json" -Raw | ConvertFrom-Json
Write-Host "`n1.3 total=$($p13.Count)"
Write-Host "--- 1.3 top files ---"
$p13 | Group-Object file | Sort-Object Count -Descending | Select-Object -First 25 | ForEach-Object { "{0,4} {1}" -f $_.Count, $_.Name }
$p13 | Where-Object { $_.file -match 'ctsSplitState|ctssch|ccd/|NodeList|Skew' } | Select-Object -First 40 | ForEach-Object { "{0}:{1}  {2}" -f $_.file, $_.line, $_.text }

