# Find 1.2 suspects that look like member fields (not just function params) and not marked_insts
$p12 = Get-Content "C:\Users\carys\cts\.cursor\nd-scan\prio_1.2_suspect.json" -Raw | ConvertFrom-Json
$interesting = $p12 | Where-Object {
  $_.text -match '(^\s*(std::)?(set|map|multiset|multimap)<.*>\s+\w+|typedef\s+std::(set|map))' -and
  $_.text -notmatch 'marked_insts|visited|isMarked|markInsts'
}
Write-Host "interesting count=$($interesting.Count)"
$interesting | Group-Object file | Sort-Object Count -Descending | Select-Object -First 20 | ForEach-Object { "{0,3} {1}" -f $_.Count, $_.Name }
Write-Host '--- sample ---'
$interesting | Select-Object -First 50 | ForEach-Object { "{0}:{1}  {2}" -f $_.file, $_.line, $_.text }

# Find 1.2 declarations that lack ndmObjPtrCmp / compareObj / ctsTreeNodeCompare / cmpByString / keyCompare
$p12 = Get-Content "C:\Users\carys\cts\.cursor\nd-scan\prio_1.2_suspect.json" -Raw | ConvertFrom-Json
$noCmp = $p12 | Where-Object { $_.text -notmatch 'ndmObjPtrCmp|compareObjPtr|ctsTreeNodeCompare|cmpByString|keyCompare|dosContainer|PtrCmp|ObjCompare' }
Write-Host "noCmp=$($noCmp.Count)"
# Focus on member fields and typedefs
$noCmp | Where-Object { $_.text -match 'typedef|^\s*std::(set|map)|^[^/]*std::(set|map)<.*>\s+_' } | Select-Object -First 40 | ForEach-Object { "{0}:{1}  {2}" -f $_.file, $_.line, $_.text }
